  '.dcards-main{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px;}', // 0.9.16：列表主列（l1 名称+owner+★ / l2 描述 / l3 元数据）
  '.dcards-l1{display:flex;align-items:baseline;gap:8px;min-width:0;}',
